input.script:
const textarea = document.querySelector('textarea[aria-label="WolframAlpha input field"]');
if (textarea) {
  textarea.value = '';
  textarea.dispatchEvent(new Event('input', {bubbles: true}));
  return 'cleared';
}
return 'not found';

const inputs = {
  '-1545134563': '120 N/m',      // spring constant
  '-1000928369': '0.12 m',        // spring equilibrium length
  '832647217': '80 °',            // initial angle from vertical
  '218898322': '0.24 m',          // initial length
  '1772288032': '1 kg',           // mass
  '1399124071': '6 s'             // time
};
for (const [id, value] of Object.entries(inputs)) {
  const el = document.getElementById(id);
  if (el) {
    el.value = value;
    el.dispatchEvent(new Event('input', {bubbles: true}));
    el.dispatchEvent(new Event('change', {bubbles: true}));
  }
}
return Object.fromEntries(Object.entries(inputs).map(([id, value]) => [id, document.getElementById(id)?.value]));

// Find the Compute button and click it
const buttons = document.querySelectorAll('button');
for (const btn of buttons) {
  if (btn.textContent.trim() === 'Compute') {
    btn.click();
    return 'clicked Compute';
  }
}
return 'Compute button not found';
